# Determinar os caracteres únicos
#itere sobre cada caractere único e conte o número encontrado na sequência
#armazene cada contagem em um dicionário. Exemplo: nt_comp['A'] = 3
#quando terminar de contar cada caractere, calcule e relate a composição de nucleotídeos e o conteúdo de GC

seq = ('')

print('Esses caracteres estão na sequência')
seq_inter = set(seq)
for nt in seq_inter:
    print(nt)

dicio = {}
for nt in seq_inter:
    contagem = seq.count(nt)
    print('O caracter ',nt,' aparece ',contagem,' vezes')
    dicio[nt]=contagem
    print(f'Composição do caractere na sequência: {contagem / len(seq):.2%}')
print(f'Essa é a composição de GC na sequência: {(int(dicio['G']) + int(dicio['C']))/len(seq):.2%}')
print(dicio)

